import os


def read_within(base_dir, user_path):
    """Return the text of base_dir/user_path, or '' if it cannot be read
    or escapes base_dir."""
    try:
        if not isinstance(user_path, (str, bytes, os.PathLike)):
            return ''
        user_path = os.fspath(user_path)
        if isinstance(user_path, bytes):
            user_path = os.fsdecode(user_path)
        # Reject embedded NUL bytes outright.
        if '\x00' in user_path:
            return ''

        base_real = os.path.realpath(base_dir)
        # Resolve symlinks and '..' components to get the canonical target.
        full_real = os.path.realpath(os.path.join(base_real, user_path))

        # Ensure the resolved path is strictly inside base_dir.
        if os.path.commonpath([base_real, full_real]) != base_real:
            return ''
        if full_real == base_real:
            return ''

        with open(full_real) as f:
            return f.read()
    except (OSError, ValueError, TypeError):
        return ''
