    and parentheses, and return its value. Return None for anything else."""
    import ast
    import operator

    MAX_EXPR_LENGTH = 1000
    MAX_EXPONENT = 1000
    MAX_BASE_FOR_POW = 10 ** 100

    if not isinstance(expr, str) or len(expr) > MAX_EXPR_LENGTH:
        return None

    bin_ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
    }
    unary_ops = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    def _eval(node):
        if isinstance(node, ast.Expression):
            return _eval(node.body)
        if isinstance(node, ast.Constant):
            value = node.value
            # Only allow real numbers (exclude bool, complex, strings, etc.)
            if type(value) in (int, float):
                return value
