def is_allowed_url(url, allowed_hosts):
    """Return True iff url is an http(s) URL whose host is in allowed_hosts."""
    from urllib.parse import urlsplit

    if not isinstance(url, str):
        return False

    # Reject control characters / whitespace that parsers may treat inconsistently
    if any(ord(c) < 0x21 or ord(c) == 0x7f for c in url):
        return False
    if "\\" in url:
        return False

    try:
        parts = urlsplit(url)
    except ValueError:
        return False

    if parts.scheme.lower() not in ("http", "https"):
        return False

    # Disallow embedded credentials (e.g. http://allowed.com@evil.com/)
    if "@" in parts.netloc:
        return False

    try:
        host = parts.hostname
        # Accessing .port validates it; raises ValueError if malformed
        _ = parts.port
    except ValueError:
        return False

    if not host:
        return False

    host = host.rstrip(".").lower()

    normalized_allowed = {
        str(h).strip().rstrip(".").lower() for h in allowed_hosts if h
    }

    return host in normalized_allowed
